import axios from 'axios'

const request = axios.create({
  baseURL: '/message-board/api',
  timeout: 10000
})

// 响应拦截器
request.interceptors.response.use(
  response => {
    const res = response.data
    if (res.code === 200) {
      return res.data
    } else {
      return Promise.reject(new Error(res.message || '请求失败'))
    }
  },
  error => {
    return Promise.reject(error)
  }
)

// ==================== 留言相关 API ====================

/** 分页查询留言列表 */
export function getMessageList(params) {
  return request.get('/message/list', { params })
}

/** 获取留言详情 */
export function getMessageDetail(id, uid) {
  return request.get(`/message/detail/${id}`, { params: { uid } })
}

/** 发布留言 */
export function publishMessage(data) {
  return request.post('/message/publish', data)
}

/** 点赞/取消点赞 */
export function toggleLike(messageId, uid) {
  return request.post('/message/like', null, { params: { messageId, uid } })
}

/** 点赞热榜 */
export function getHotByLike(topN = 10) {
  return request.get('/message/hot/like', { params: { topN } })
}

/** 评论热榜 */
export function getHotByComment(topN = 10) {
  return request.get('/message/hot/comment', { params: { topN } })
}

// ==================== 评论相关 API ====================

/** 发表评论 */
export function publishComment(data) {
  return request.post('/comment/publish', data)
}
